const express = require("express");

const app = express();

app.use(express.json());

const events = [
  { id: 1, title: "Open Mic", category: "arts" },
  { id: 2, title: "Career Fair", category: "career" },
  { id: 3, title: "Gallery Walk", category: "arts" },
];

function validateNewEvent(input) {
  const fields = [];

  if (!input.title || typeof input.title !== "string") {
    fields.push("title");
  }

  if (!input.category || typeof input.category !== "string") {
    fields.push("category");
  }

  return fields;
}

app.get("/api/events", (req, res) => {
  const category = req.query.category;
  const result = category
    ? events.filter((event) => event.category === category)
    : events;

  return res.status(200).json(result);
});

app.get("/api/events/:id", (req, res) => {
  const id = Number(req.params.id);
  const event = events.find((item) => item.id === id);

  if (!event) {
    return res.status(404).json({ error: "Event not found" });
  }

  return res.status(200).json(event);
});

app.post("/api/events", (req, res) => {
  const fields = validateNewEvent(req.body);

  if (fields.length > 0) {
    return res.status(400).json({
      error: "Validation failed",
      fields,
    });
  }

  const nextId =
    events.length > 0
      ? Math.max(...events.map((event) => event.id)) + 1
      : 1;

  const event = {
    id: nextId,
    title: req.body.title,
    category: req.body.category,
  };

  events.push(event);
  return res.status(201).json(event);
});

app.patch("/api/events/:id", (req, res) => {
  const id = Number(req.params.id);
  const event = events.find((item) => item.id === id);

  if (!event) {
    return res.status(404).json({ error: "Event not found" });
  }

  if (req.body.title !== undefined) {
    event.title = req.body.title;
  }

  if (req.body.category !== undefined) {
    event.category = req.body.category;
  }

  return res.status(200).json(event);
});

app.delete("/api/events/:id", (req, res) => {
  const id = Number(req.params.id);
  const index = events.findIndex((item) => item.id === id);

  if (index === -1) {
    return res.status(404).json({ error: "Event not found" });
  }

  events.splice(index, 1);
  return res.status(204).send();
});

const server = app.listen(3000, "127.0.0.1", async () => {
  const baseUrl = "http://127.0.0.1:3000";

  const createResponse = await fetch(`${baseUrl}/api/events`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({
      title: "Coding Meetup",
      category: "technology",
    }),
  });
  const created = await createResponse.json();

  const invalidCreateResponse = await fetch(`${baseUrl}/api/events`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ title: "" }),
  });

  const patchResponse = await fetch(`${baseUrl}/api/events/${created.id}`, {
    method: "PATCH",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ category: "community" }),
  });

  const deleteResponse = await fetch(`${baseUrl}/api/events/${created.id}`, {
    method: "DELETE",
  });

  const missingPatchResponse = await fetch(`${baseUrl}/api/events/999`, {
    method: "PATCH",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ title: "Missing" }),
  });

  const missingDeleteResponse = await fetch(`${baseUrl}/api/events/999`, {
    method: "DELETE",
  });

  console.log("create", createResponse.status);
  console.log("invalid create", invalidCreateResponse.status);
  console.log("patch", patchResponse.status);
  console.log("delete", deleteResponse.status);
  console.log("missing patch", missingPatchResponse.status);
  console.log("missing delete", missingDeleteResponse.status);

  server.close();
});

