const express = require("express");
const { mkdirSync } = require("node:fs");
const { DatabaseSync } = require("node:sqlite");

const app = express();
app.use(express.json());

mkdirSync("data", { recursive: true });
const db = new DatabaseSync("data/events.db");

db.exec(`
  CREATE TABLE IF NOT EXISTS events (
    id INTEGER PRIMARY KEY,
    title TEXT NOT NULL,
    category TEXT NOT NULL
  )
`);

const countRow = db.prepare("SELECT COUNT(*) AS count FROM events").get();

if (countRow.count === 0) {
  const seedEvent = db.prepare(`
    INSERT INTO events (id, title, category)
    VALUES (?, ?, ?)
  `);

  seedEvent.run(1, "Open Mic", "arts");
  seedEvent.run(2, "Career Fair", "career");
  seedEvent.run(3, "Gallery Walk", "arts");
}

function validateNewEvent(input) {
  const fields = [];

  if (!input.title || typeof input.title !== "string") {
    fields.push("title");
  }

  if (!input.category || typeof input.category !== "string") {
    fields.push("category");
  }

  return fields;
}

app.get("/api/events", (req, res) => {
  const category = req.query.category;

  if (category) {
    const events = db
      .prepare(`
        SELECT id, title, category
        FROM events
        WHERE category = ?
        ORDER BY id
      `)
      .all(category);

    return res.status(200).json(events);
  }

  const events = db
    .prepare(`
      SELECT id, title, category
      FROM events
      ORDER BY id
    `)
    .all();

  return res.status(200).json(events);
});

app.get("/api/events/:id", (req, res) => {
  const id = Number(req.params.id);
  const event = db
    .prepare(`
      SELECT id, title, category
      FROM events
      WHERE id = ?
    `)
    .get(id);

  if (!event) {
    return res.status(404).json({ error: "Event not found" });
  }

  return res.status(200).json(event);
});

app.post("/api/events", (req, res) => {
  const fields = validateNewEvent(req.body);

  if (fields.length > 0) {
    return res.status(400).json({
      error: "Validation failed",
      fields,
    });
  }

  const result = db
    .prepare(`
      INSERT INTO events (title, category)
      VALUES (?, ?)
    `)
    .run(req.body.title, req.body.category);

  const event = db
    .prepare(`
      SELECT id, title, category
      FROM events
      WHERE id = ?
    `)
    .get(Number(result.lastInsertRowid));

  return res.status(201).json(event);
});

app.patch("/api/events/:id", (req, res) => {
  const id = Number(req.params.id);
  const current = db
    .prepare(`
      SELECT id, title, category
      FROM events
      WHERE id = ?
    `)
    .get(id);

  if (!current) {
    return res.status(404).json({ error: "Event not found" });
  }

  const title =
    req.body.title !== undefined ? req.body.title : current.title;
  const category =
    req.body.category !== undefined ? req.body.category : current.category;

  db.prepare(`
    UPDATE events
    SET title = ?, category = ?
    WHERE id = ?
  `).run(title, category, id);

  const updated = db
    .prepare(`
      SELECT id, title, category
      FROM events
      WHERE id = ?
    `)
    .get(id);

  return res.status(200).json(updated);
});

app.delete("/api/events/:id", (req, res) => {
  const id = Number(req.params.id);
  const result = db
    .prepare("DELETE FROM events WHERE id = ?")
    .run(id);

  if (result.changes === 0) {
    return res.status(404).json({ error: "Event not found" });
  }

  return res.status(204).send();
});

app.listen(3000, "127.0.0.1", () => {
  console.log("API listening on http://127.0.0.1:3000");
});

